script:
{ d=$(mktemp -d); cd "$d"; set -m; /usr/bin/python3 -c 'import os,signal,pathlib,time
signal.signal(signal.SIGUSR1,lambda *a: pathlib.Path("parent-hit").write_text("yes"))
c=os.fork()
if c==0:
 signal.signal(signal.SIGUSR1,lambda *a: pathlib.Path("child-hit").write_text("yes"))
 pathlib.Path("childpid").write_text(str(os.getpid()))
else:
 pathlib.Path("parentpid").write_text(str(os.getpid()))
while True: time.sleep(.02)
' & p=$!; until [ -s childpid ] && [ -s parentpid ]; do /bin/sleep .01; done; kill -USR1 %1; echo kill=$?; i=0; until [ -s parent-hit ] || [ $i -ge 300 ]; do /bin/sleep .01; i=$((i+1)); done; /bin/sleep .2; if [ -s parent-hit ]; then echo parent=hit; else echo parent=miss; fi; if [ -s child-hit ]; then echo child=hit; else echo child=miss; fi; read c <childpid; read q <parentpid; /bin/kill -KILL "$c" "$q" 2>/dev/null; wait 2>/dev/null; cd /; rm -rf "$d"; } 2>/dev/null

